import {
	Component,
	Element,
	Event,
	type EventEmitter,
	Fragment,
	Host,
	Prop,
	State,
	h,
} from "@stencil/core";
import { alertsNegativeLarge, remove } from "../../../icons";
import { generateShortID } from "../../utils/function-helper";
import getBootstrapConfig from "../../utils/getBootstrapConfig";
import { internationalization } from "../../utils/i18n/translations";
import { hasSlot } from "../../utils/slot";
import translations from "./i18n";

interface File {
	state: string;
}

/**
 * @since 1.1.5
 * @status stable
 *
 * @slot - The uploader's file list slot.
 * @slot label - The uploader's label.
 * @slot label-suffix - The uploader's label suffix.
 * @slot container-icon - The upload icon slot.
 * @slot optional-title - The button trigger version's optional title.
 * @slot optional-text - The button trigger version, it is required to have a description stating the file restrictions, like file format and file size.
 * @slot trigger - The select file trigger.
 * @slot supplemental-text - A supplementary text in the container, such as file size or file type restrictions.
 *
 * @part base - The base wrapper.
 * @part drop-zone - The drop zone.
 * @part label - Drag and drop's content wrapper
 * @part container-icon - upload icon
 * @part content - Main and supplemental-text content wrapper.
 * @part supplemental-text - The supplementary text.
 * @part error-message - The error message wrapper.
 * @part list-container - The file list wrapper.
 *
 * @dataTestId dropZone - The file drop zone.
 * @dataTestId fileSelect-input - The input element which triggers the file select.
 * @dataTestId errorMessage-removeIcon - The error message remove button wrapper.
 */

@Component({
	tag: "hbr-uploader",
	styleUrl: "uploader.scss",
	shadow: true,
	formAssociated: true,
})
export class Uploader {
	input: HTMLInputElement;
	dropZone: HTMLDivElement;
	errorMessage: HTMLDivElement;

	@Element() host: HTMLHbrUploaderElement;

	@State() hasFileList = false;
	@State() hasOptionalTitle = false;
	@State() hasOptionalText = false;
	@State() hasOptionalContent = false;
	@State() hasContainerIcon = false;
	@State() hasLabelContainer = false;
	@State() hasSupplementalText = false;

	/** Set to true to disable. */
	@Prop({ reflect: true, mutable: true }) disabled = false;

	@Prop() label: string;

	/** The uploader's size. */
	@Prop({ reflect: true }) size: "small" | "medium" = "medium";

	/** Set to true to draggable. */
	@Prop({ reflect: true }) container: boolean;

	/** Makes a container uploader and its file items non-interactive. */
	@Prop({ reflect: true }) readonly = false;

	/** Array of files. */
	@Prop() files: File[] = [];

	/** Allow multiple files to upload  */
	@Prop({ reflect: true }) multiple: boolean;

	/** Set accepted file types. */
	@Prop() accept: string | string[];

	/** Error message */
	@Prop() error: string;

	/** The name of the uploader. */
	@Prop({ reflect: true }) name = "";

	@State() hasContent = false;
	@State() hasHelpTextSlot = false;
	@State() hasLabelSlot = false;
	@State() inputId: string = this.name || generateShortID();

	/** Emitted when the file(s) dropped. */
	@Event({ eventName: "hbr-file-drop" }) hbrFileDrop: EventEmitter;

	/** Emitted when there is an error */
	@Event({ eventName: "hbr-error" }) hbrError: EventEmitter;

	/** Emitted when a file is selected */
	@Event({ eventName: "hbr-select" }) hbrSelect: EventEmitter<{
		files: FileList;
		event?: KeyboardEvent;
	}>;

	private async handleChange(event) {
		if (this.container && this.readonly) return;
		const input = event.target as HTMLInputElement;
		const files = await input.files;
		this.hbrSelect.emit({ files, event });
		this.input.value = "";
	}

	private handleDefaultSlotChange(e) {
		this.hasFileList = hasSlot(this.host);
		if (this.hasFileList) {
			const slot = e.target as HTMLSlotElement;
			const slottedElements = [
				...slot.assignedElements({ flatten: true }),
			] as HTMLHbrFileItemElement[];
			const notMedium = this.size !== "medium";
			const { multiple } = this;

			if (slottedElements.length) {
				slottedElements.forEach((file, idx) => {
					file.toggleAttribute("readonly", this.container && this.readonly);
					let newIndex = idx;
					if (multiple) {
						newIndex++;
						file.setAttribute("data-idx", `${newIndex}`);
					} else {
						file.setAttribute("data-idx", "0");
					}

					if (notMedium) {
						file.size = this.size;
					}
					return file;
				});
			}
		}
	}

	private handleSlotChange() {
		this.hasLabelSlot = hasSlot(this.host, "label");
		this.hasOptionalTitle = hasSlot(this.host, "optional-title");
		this.hasOptionalText = hasSlot(this.host, "optional-text");
		this.hasContainerIcon = hasSlot(this.host, "container-icon");
		this.hasSupplementalText = hasSlot(this.host, "supplemental-text");
		this.hasOptionalContent =
			!this.container && (this.hasOptionalTitle || this.hasOptionalText);
	}

	private handleDragEnter() {
		if (this.container && this.readonly) return;
		this.dropZone?.classList.add("uploader__dropZone-highlight");
	}

	private handleDragOver(event) {
		event.preventDefault();
		if (this.container && this.readonly) return false;
		this.dropZone?.classList.add("uploader__dropZone-highlight");
		return false;
	}
	private handleDragLeave() {
		this.dropZone?.classList.remove("uploader__dropZone-highlight");
	}

	private handleDrop(event) {
		event.preventDefault();
		if (this.container && this.readonly) return;
		this.dropZone?.classList.remove("uploader__dropZone-highlight");

		const { dataTransfer } = event;
		const queue = [...event.dataTransfer.items].map((item) => item.getAsFile());
		const responses = [];
		for (const file of queue) {
			responses.push(file);
		}

		if (!this.multiple) {
			if (1 < dataTransfer.files?.length) {
				this.error = internationalization(translations, "multiFileError");
				this.hbrError.emit({ files: responses, error: this.error });
				return;
			}
			if (this.error) {
				this.error = undefined;
			}
		}

		return this.hbrFileDrop.emit({ files: responses, dataTransfer });
	}

	private handleErrorRemoveClick() {
		this.errorMessage.classList.add("hbr-hide");
		this.error = undefined;
	}

	private handleFocus(event) {
		if (this.dropZone) {
			const mouseEvent = event.relatedTarget;
			if (mouseEvent)
				this.dropZone.classList.add("uploader__input-kb--focused");
		}
	}

	private handleTriggerClick(event) {
		event.preventDefault();
		event.stopPropagation();
		if (this.container && this.readonly) return;
		this.input?.click();
	}

	private handleBlur() {
		this.dropZone?.classList.remove("uploader__input-kb--focused");
	}

	getLabel() {
		const { inputId, name, multiple, disabled } = this;
		const readonlyContainer = Boolean(this.container && this.readonly);
		const acceptType = Array.isArray(this.accept)
			? this.accept.join(",")
			: (this.accept as string);

		return (
			<Fragment>
				<div
					class={{
						"uploader__optional-content": true,
						"uploader--has-optional-content": this.hasOptionalContent,
					}}
				>
					<slot name="optional-title" onSlotchange={this.handleSlotChange} />
					<slot name="optional-text" onSlotchange={this.handleSlotChange} />
				</div>
				<input
					id={inputId}
					class={"uploader__input"}
					type="file"
					name={name}
					disabled={disabled || readonlyContainer}
					onChange={this.handleChange.bind(this)}
					accept={acceptType}
					multiple={multiple}
					ref={(el) => {
						this.input = el;
					}}
					data-testid="fileSelect-input"
					onFocus={this.handleFocus.bind(this)}
					onBlur={this.handleBlur.bind(this)}
				/>
				<label part="label" htmlFor={inputId}>
					<span part="container-icon" class="uploader__icon-upload">
						<slot name="container-icon" onSlotchange={this.handleSlotChange} />
					</span>
					<div part="content" class="uploader__content">
						<span onClick={this.handleTriggerClick.bind(this)}>
							<slot name="trigger" onSlotchange={this.handleSlotChange} />
						</span>
						{this.hasSupplementalText ? (
							<span class="uploader__supplemental-text">
								<slot
									name="supplemental-text"
									onSlotchange={this.handleSlotChange}
								/>
							</span>
						) : (
							""
						)}
					</div>
				</label>
			</Fragment>
		);
	}

	removeSessionStorage() {
		sessionStorage["hbr__session-uploadInProgress"] = undefined;
		return;
	}

	setSessionStorage() {
		const { files } = this;
		if (files?.length) {
			if (files.some((file) => file.state === "progress")) {
				const SESSION_STORAGE = "hbr__session-uploadInProgress";
				sessionStorage.setItem(SESSION_STORAGE, "true");
			} else {
				this.removeSessionStorage();
			}
		} else {
			this.removeSessionStorage();
		}
	}

	connectedCallback() {
		this.handleSlotChange = this.handleSlotChange.bind(this);
	}

	componentWillLoad() {
		this.handleSlotChange();
		/** For preset file item like test use case */
		const fileItem: HTMLHbrFileItemElement =
			this.host.querySelector("hbr-file-item");
		if (fileItem) {
			if (this.multiple) {
				fileItem.setAttribute("data-idx", "1");
			} else {
				fileItem.setAttribute("data-idx", "0");
			}
		}
	}

	disconnectedCallback() {
		this.removeSessionStorage();
	}

	componentDidRender() {
		const readonlyContainer = Boolean(this.container && this.readonly);
		this.host.querySelectorAll("hbr-file-item").forEach((fileItem) => {
			fileItem.toggleAttribute("readonly", readonlyContainer);
		});
		this.setSessionStorage();
	}

	render() {
		const customSystemIcons = getBootstrapConfig()?.systemIcons;
		const { container, size, inputId, disabled, multiple } = this;
		const readonlyContainer = Boolean(container && this.readonly);
		const showError = this.error && typeof this.error === "string";
		const UL = multiple ? "ul" : "div";
		const containsLabel: boolean = !!(this.hasLabelSlot || this.label);

		return (
			<Host>
				{containsLabel && (
					<div class={"uploader__label"}>
						<slot name="label">{this.label}</slot>
						<slot name="label-suffix" />
					</div>
				)}
				<div
					part="base"
					class={{
						uploader: true,
						"uploader--draggable": container,
						...(size ? { [`uploader--${size}`]: true } : null),
						"uploader--multiple": multiple,
						"uploader--disabled": disabled,
						"uploader--readonly": readonlyContainer,
						"uploader--error": showError,
						/** slot */
						"uploader--has-file-list": this.hasFileList,
						"uploader--has-optional-title": this.hasOptionalTitle,
						"uploader--has-optional-text": this.hasOptionalText,
						"uploader--has-container-icon": this.hasContainerIcon,
						"uploader--has-supplemental-text": this.hasSupplementalText,
					}}
				>
					{this.container ? (
						<div
							id={`hbr--id_${inputId}-uploader--drop`}
							onDragEnter={this.handleDragEnter.bind(this)}
							onDragOver={this.handleDragOver.bind(this)}
							onDragLeave={this.handleDragLeave.bind(this)}
							onDrop={this.handleDrop.bind(this)}
							part="drop-zone"
							class="uploader__drop-container"
							ref={(el) => {
								this.dropZone = el;
							}}
							data-testid="dropZone"
						>
							{this.getLabel()}
						</div>
					) : (
						this.getLabel()
					)}
					{showError ? (
						<div
							class="uploader__error-message"
							part="error-message"
							ref={(el) => {
								this.errorMessage = el;
							}}
						>
							<hbr-icon
								class="uploader__error-icon"
								asset={
									customSystemIcons?.["alerts-negative-large"] ||
									alertsNegativeLarge
								}
							/>
							{this.error}
							<hbr-icon-button
								exportparts="base:error-remove-button"
								asset={customSystemIcons?.remove || remove}
								class="uploader__error-remove"
								arialabel="Remove this error message"
								data-testid="errorMessage-removeIcon"
								onClick={this.handleErrorRemoveClick.bind(this)}
							/>
						</div>
					) : (
						""
					)}
					<UL
						part="list-container"
						class={{
							"uploader__files-container": true,
							"uploader--has-file-list": this.hasFileList,
						}}
					>
						<slot onSlotchange={this.handleDefaultSlotChange.bind(this)} />
					</UL>
				</div>
			</Host>
		);
	}
}
